/* Extra styles for the Food, Neighborhoods, Things to do, Account, and Ask Dillon pages. */
.save { position: absolute; top: 16px; right: 16px; width: 44px; height: 44px; border-radius: 999px; border: 1.5px solid var(--navy); background: #fff; display: flex; align-items: center; justify-content: center; padding: 0; z-index: 2; }
.save svg { width: 20px; height: 20px; fill: none; stroke: var(--navy); stroke-width: 2; }
.save.on { background: var(--navy); } .save.on svg { fill: #fff; stroke: #fff; }
.tcard { position: relative; }
.tcard > a { display: block; padding: 24px; text-decoration: none; color: inherit; }
.tcard h4 { padding-right: 52px; }
.tabs { display: flex; flex-wrap: wrap; gap: 10px; }
button.chip { cursor: pointer; font-family: inherit; }
.hidden { display: none !important; }
.search { max-width: 520px; }
.filters { display: grid; grid-template-columns: 2fr 1fr; gap: 16px; align-items: end; max-width: 720px; }
@media (max-width: 600px) { .filters { grid-template-columns: 1fr; } }
.kv { display: grid; gap: 12px; }
.panel { background: #fff; border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); padding: 32px; }
.toggle-row { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.menu { display: block; padding: 12px 0; border-bottom: 1px solid var(--line); color: var(--navy); text-decoration: none; font-weight: 700; }
