scripts/legacy-to-public.mjs:
// Builds data/profiles.csv and data/content.csv from the old site data saved in legacy/.
// This only fills the preview with realistic rows until the sheet is connected. The sheet export replaces these files.
import fs from 'node:fs';
import { createRequire } from 'node:module';
const core = createRequire(import.meta.url)('./sheet-export-core.cjs');
function parseCSV(text) { const rows = []; let row = [], f = '', q = false; for (let i = 0; i < text.length; i++) { const c = text[i]; if (q) { if (c === '"') { if (text[i + 1] === '"') { f += '"'; i++; } else q = false; } else f += c; } else if (c === '"') q = true; else if (c === ',') { row.push(f); f = ''; } else if (c === '\n') { row.push(f); rows.push(row); row = []; f = ''; } else if (c !== '\r') f += c; } if (f.length || row.length) { row.push(f); rows.push(row); } return rows.filter((r) => r.some((x) => x !== '')); }
const objs = (t) => { const [h, ...r] = parseCSV(t); return r.map((x) => Object.fromEntries(h.map((k, i) => [k, x[i] || '']))); };
const P = objs(fs.readFileSync('legacy/profiles.csv', 'utf8')), C = objs(fs.readFileSync('legacy/content.csv', 'utf8'));
fs.mkdirSync('data', { recursive: true });
fs.writeFileSync('data/profiles.csv', core.toCSV(core.toPublicProfiles(P, { mode: 'preview' }), core.PROFILE_COLUMNS));
fs.writeFileSync('data/content.csv', core.toCSV(core.toPublicContent(C, { mode: 'preview' }), core.CONTENT_COLUMNS));
console.log('wrote data/profiles.csv and data/content.csv');

src/pages/food/index.astro:
---
import Base from '../../layouts/Base.astro';
import Prefs from '../../components/Prefs.astro';
import '../../styles/pages.css';
import { businesses, href, url } from '../../lib/data';
import { category, foodTab, cuisineRegion, topRating, FOOD_TABS, WORLD } from '../../lib/helpers';

const cards = businesses().filter((b) => b.status !== 'Closed').map((b) => ({ b, cat: category(b), tab: foodTab(b), world: cuisineRegion(b), rating: topRating(b.name) }))
  .sort((x, y) => y.rating - x.rating || x.b.name.localeCompare(y.b.name));
const areaCount: Record<string, number> = {};
cards.forEach((c) => { if (c.b.area) areaCount[c.b.area] = (areaCount[c.b.area] || 0) + 1; });
const areas = Object.keys(areaCount).sort();
const topAreas = Object.entries(areaCount).sort((a, b) => b[1] - a[1]).slice(0, 6).map((x) => x[0]);
const worldLists: Record<string, typeof cards> = {};
WORLD.forEach(([k]) => { worldLists[k] = (k === 'all' ? cards.filter((c) => c.world) : cards.filter((c) => c.world === k)).slice(0, 9); });
// small index the page script uses for "Eat by neighborhood" and for saved places
const index = cards.map((c) => ({ s: c.b.slug, n: c.b.name, a: c.b.area, c: c.cat, r: c.rating, u: href(c.b) }));
const heart = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21s-7-4.6-9.5-9A5.5 5.5 0 0 1 12 6a5.5 5.5 0 0 1 9.5 6c-2.5 4.4-9.5 9-9.5 9z"/></svg>';
---
<Base title="Food" active="Food" description="Reviews from Sara, with a rating you can trust.">
  <section class="band hero">
    <div class="wrap">
      <p class="eyebrow">Eat like a local</p>
      <h1 style="margin-bottom:12px">What sounds good?</h1>
      <p class="lead" style="margin-bottom:28px">Reviews from Sara, with a rating you can trust. Start with a craving, an area, or what is new.</p>
      <div class="card pad"><div class="filters">
        <div><label for="f-q">Search</label><input id="f-q" type="search" placeholder="Try thai, coffee, or a place name" /></div>
        <div><label for="f-area">Area</label><select id="f-area"><option value="">Anywhere</option>{areas.map((a) => <option>{a}</option>)}</select></div>
      </div></div>
      <div class="tabs" id="f-tabs" style="margin-top:20px">{FOOD_TABS.map(([k, l], i) => <button class={`chip${i === 0 ? ' on' : ''}`} data-tab={k} aria-pressed={i === 0 ? 'true' : 'false'}>{l}</button>)}</div>
    </div>
  </section>

  <section class="band" id="browse">
    <div class="wrap">
      <div style="display:flex;justify-content:space-between;align-items:end;margin-bottom:24px;flex-wrap:wrap;gap:12px">
        <div><p class="eyebrow">Browse</p><h2>Every place we have reviewed</h2><p class="meta" id="f-count" style="margin-top:6px">{cards.length} places</p></div>
        <a class="btn line" href={url('/account#saved')}>Saved places (<span id="f-saved">0</span>)</a>
      </div>
      <div class="grid g3" id="f-grid">
        {cards.map((c) => (
          <div class="card tcard f-item" data-area={c.b.area} data-tab={c.tab} data-name={`${c.b.name} ${c.cat} ${c.b.area}`.toLowerCase()}>
            <a href={href(c.b)}>
              {c.rating > 0 && <span class="tag">{c.rating} out of 5</span>}
              <h4 style="margin:12px 0 4px">{c.b.name}</h4><p class="meta">{[c.cat, c.b.area].filter(Boolean).join(', ')}</p>
            </a>
            <button class="save" data-slug={c.b.slug} data-name={c.b.name} set:html={heart}></button>
          </div>
        ))}
      </div>
      <div class="card pad hidden" id="f-empty" style="margin-top:8px"><b>No places match yet.</b><p class="meta" style="margin-top:4px">Try a different area or search.</p></div>
    </div>
  </section>

  <section class="band tint">
    <div class="wrap">
      <p class="eyebrow">Eat around the world</p>
      <h2 style="margin-bottom:24px">Follow a cuisine</h2>
      <div class="tabs" id="w-tabs" style="margin-bottom:24px">{WORLD.map(([k, l], i) => <button class={`chip${i === 0 ? ' on' : ''}`} data-world={k} aria-pressed={i === 0 ? 'true' : 'false'}>{l}</button>)}</div>
      {WORLD.map(([k], i) => (
        <div class={`w-block${i === 0 ? '' : ' hidden'}`} data-world={k}>
          {worldLists[k].length ? (
            <div class="grid g3">{worldLists[k].map((c) => <a class="card pad" href={href(c.b)} style="text-decoration:none">{c.rating > 0 && <span class="tag">{c.rating} out of 5</span>}<h4 style="margin:12px 0 4px">{c.b.name}</h4><p class="meta">{[c.cat, c.b.area].filter(Boolean).join(', ')}</p></a>)}</div>
          ) : (
            <div class="card pad" style="max-width:640px"><b>We are still finding places for this region.</b><p class="meta" style="margin-top:4px">Know a favorite? Tell us and we will look into it.</p></div>
          )}
        </div>
      ))}
    </div>
  </section>

  <section class="band">
    <div class="wrap">
      <p class="eyebrow">Eat by neighborhood</p>
      <h2 style="margin-bottom:12px">Start close to home</h2>
      <p class="meta" id="n-note" style="font-size:16px;margin-bottom:24px">Showing the busiest areas. Set your area in your account and it opens first.</p>
      <div class="tabs" id="n-tabs" style="margin-bottom:24px"></div>
      <div class="grid g3" id="n-grid"></div>
      <p style="margin-top:24px"><a id="n-link" href={url('/neighborhoods')} style="font-weight:700">See all neighborhoods</a></p>
    </div>
  </section>

  <Prefs />
  <script is:inline define:vars={{ INDEX: index, TOP: topAreas, BASE: url('') }}>
    var TLD = window.TL;
    // filters
    var q = document.getElementById('f-q'), sel = document.getElementById('f-area'), items = [].slice.call(document.querySelectorAll('.f-item')), tab = 'all';
    function run() {
      var term = q.value.trim().toLowerCase(), a = sel.value, n = 0;
      items.forEach(function (i) { var ok = (!a || i.dataset.area === a) && (tab === 'all' || i.dataset.tab === tab) && (!term || i.dataset.name.indexOf(term) > -1); i.classList.toggle('hidden', !ok); if (ok) n++; });
      document.getElementById('f-count').textContent = n + (n === 1 ? ' place' : ' places');
      document.getElementById('f-empty').classList.toggle('hidden', n > 0);
    }
    var pre = new URLSearchParams(location.search).get('area'); if (pre) sel.value = pre;
    q.addEventListener('input', run); sel.addEventListener('change', run);
    document.getElementById('f-tabs').addEventListener('click', function (e) { var b = e.target.closest('button'); if (!b) return; tab = b.dataset.tab; [].forEach.call(this.children, function (c) { c.classList.toggle('on', c === b); c.setAttribute('aria-pressed', c === b ? 'true' : 'false'); }); run(); });
    run();
    // cuisine tabs
    document.getElementById('w-tabs').addEventListener('click', function (e) { var b = e.target.closest('button'); if (!b) return; [].forEach.call(this.children, function (c) { c.classList.toggle('on', c === b); c.setAttribute('aria-pressed', c === b ? 'true' : 'false'); });
      document.querySelectorAll('.w-block').forEach(function (d) { d.classList.toggle('hidden', d.dataset.world !== b.dataset.world); }); });
    // saved count
    function savedCount() { document.getElementById('f-saved').textContent = TLD.saved().length; }
    document.addEventListener('tl:saved', savedCount); savedCount();
    // eat by neighborhood: the reader's area and followed areas come first
    var mine = TLD.area(), fol = TLD.follows(), names = [];
    [mine].concat(fol, TOP).forEach(function (a) { if (a && names.indexOf(a) < 0) names.push(a); });
    names = names.slice(0, 8);
    var current = names[0], tabs = document.getElementById('n-tabs'), grid = document.getElementById('n-grid');
    function label(a) { return a + (a === mine ? ' (your area)' : fol.indexOf(a) > -1 ? ' (following)' : ''); }
    function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]; }); }
    function draw() {
      tabs.innerHTML = names.map(function (a) { return '<button class="chip' + (a === current ? ' on' : '') + '" data-a="' + esc(a) + '" aria-pressed="' + (a === current) + '">' + esc(label(a)) + '</button>'; }).join('');
      var list = INDEX.filter(function (x) { return x.a === current; }).sort(function (a, b) { return b.r - a.r; }).slice(0, 6);
      grid.innerHTML = list.length ? list.map(function (x) { return '<a class="card pad" href="' + esc(x.u) + '" style="text-decoration:none">' + (x.r ? '<span class="tag">' + x.r + ' out of 5</span>' : '') + '<h4 style="margin:12px 0 4px">' + esc(x.n) + '</h4><p class="meta">' + esc([x.c, x.a].filter(Boolean).join(', ')) + '</p></a>'; }).join('') : '<div class="card pad" style="max-width:640px"><b>No reviews here yet.</b><p class="meta" style="margin-top:4px">We are adding more every week.</p></div>';
      document.getElementById('n-note').textContent = current === mine ? 'Showing your area first.' : fol.indexOf(current) > -1 ? 'Showing an area you follow.' : 'Showing the busiest areas. Set your area in your account and it opens first.';
    }
    tabs.addEventListener('click', function (e) { var b = e.target.closest('button'); if (!b) return; current = b.dataset.a; draw(); });
    draw();
  </script>
</Base>

src/pages/neighborhoods/[slug].astro:
---
import Base from '../../layouts/Base.astro';
import Prefs from '../../components/Prefs.astro';
import '../../styles/pages.css';
import { href, url } from '../../lib/data';
import { areaPages, bizIn, subsIn, placesIn, topRating, category, cleanList } from '../../lib/helpers';
import { config } from '../../config';
export function getStaticPaths() { return areaPages().map((p) => ({ params: { slug: p.slug }, props: { p } })); }
const { p } = Astro.props;
const biz = bizIn(p.name).map((b) => ({ b, r: topRating(b.name) })).sort((x, y) => y.r - x.r).slice(0, 8);
const bizTotal = bizIn(p.name).length;
const subs = subsIn(p.name), places = placesIn(p.name).slice(0, 6);
const glance = p.bestFor || p.typicalHomes || p.schools;
const schools = cleanList(p.schools);
const label = p.type === 'City' ? 'City guide' : p.type === 'Area' ? 'Area guide' : 'Neighborhood guide';
---
<Base title={p.name} description={p.summary} active="Neighborhoods">
  <section class="band hero">
    <div class="wrap">
      <p class="meta" style="margin-bottom:12px"><a href={url('/neighborhoods')} style="font-weight:700">Neighborhoods</a> &rsaquo; {p.name}</p>
      <div style="display:flex;gap:8px;margin-bottom:16px;flex-wrap:wrap"><span class="tag">{label}</span>{p.region && <span class="tag soft">{p.region}</span>}</div>
      <h1 style="margin-bottom:16px">{p.name}</h1>
      {p.summary && <p class="lead" style="margin-bottom:28px">{p.summary}</p>}
      <div style="display:flex;gap:12px;flex-wrap:wrap"><button class="btn" id="set-area" data-name={p.name}>Make this my area</button><button class="btn line" id="follow" data-name={p.name}>Follow {p.name}</button><a class="btn line" href={url('/ask-dillon')}>Ask Dillon</a></div>
    </div>
  </section>

  {glance && (
    <section class="band">
      <div class="wrap" style="display:grid;grid-template-columns:repeat(12,minmax(0,1fr));column-gap:24px;align-items:start">
        <div style="grid-column:span 5">
          <p class="eyebrow">At a glance</p><h2 style="margin-bottom:24px">Living in {p.name}</h2>
          <div class="card pad">
            {p.bestFor && <p class="fact"><span>Best for</span><b>{p.bestFor}</b></p>}
            {p.typicalHomes && <p class="fact"><span>Typical homes</span><b>{p.typicalHomes}</b></p>}
            {schools && <p class="fact"><span>Schools</span><b>{schools}</b></p>}
          </div>
        </div>
        {p.localTake && (
          <div style="grid-column:span 7"><div style="background:var(--butter);border-radius:12px;padding:40px"><p class="eyebrow" style="color:var(--navy)">Our local take</p><p style="font-family:var(--serif);font-weight:600;font-size:26px;line-height:1.3">{p.localTake}</p></div></div>
        )}
      </div>
    </section>
  )}

  <section class="band" style="padding-top:0">
    <div class="wrap">
      <div class="card pad pick" style="padding:32px;max-width:760px">
        <p class="eyebrow">Locally for {p.name}</p>
        <h3 style="margin-bottom:8px">A closer look at where you live.</h3>
        <p class="meta" style="margin-bottom:20px;font-size:16px">Your neighborhood, in your inbox. Free with your account.</p>
        <form action={config.newsletterAction} method="post" style="display:flex;gap:10px;flex-wrap:wrap">
          <div style="flex:1;min-width:220px"><label class="sr" for="loc-email">Your email</label><input id="loc-email" name="email" type="email" required placeholder="name@email.com" /></div>
          <input type="text" name="company" tabindex="-1" autocomplete="off" aria-hidden="true" style="position:absolute;left:-9999px" />
          <input type="hidden" name="return" class="nl-return" />
          <button class="btn" type="submit">Get Locally</button>
        </form>
      </div>
    </div>
  </section>

  {biz.length > 0 && (
    <section class="band tint">
      <div class="wrap">
        <p class="eyebrow">Eat and explore</p><h2 style="margin-bottom:28px">Places we reviewed in {p.name}</h2>
        <div class="grid g4">
          {biz.map(({ b, r }) => <a class="card pad" href={href(b)} style="text-decoration:none">{r > 0 && <span class="tag">{r} out of 5</span>}<h4 style="margin:12px 0 4px">{b.name}</h4><p class="meta">{category(b)}</p></a>)}
        </div>
        {bizTotal > biz.length && <p style="margin-top:24px"><a href={url(`/food?area=${encodeURIComponent(p.name)}`)} style="font-weight:700">See all {bizTotal} places in {p.name}</a></p>}
      </div>
    </section>
  )}

  {places.length > 0 && (
    <section class="band">
      <div class="wrap">
        <p class="eyebrow">Things to do</p><h2 style="margin-bottom:28px">Places to visit near {p.name}</h2>
        <div class="grid g3">{places.map((x) => <a class="card pad" href={href(x)} style="text-decoration:none"><h4 style="margin-bottom:4px">{x.name}</h4><p class="meta">{x.subCategory || x.postalCity}</p></a>)}</div>
      </div>
    </section>
  )}

  {subs.length > 0 && (
    <section class="band tint">
      <div class="wrap">
        <p class="eyebrow">Subdivisions</p><h2 style="margin-bottom:28px">Know the streets in {p.name}</h2>
        <div class="chips">{subs.slice(0, 40).map((s) => <a class="chip" href={href(s)}>{s.name}</a>)}</div>
        {subs.length > 40 && <p class="meta" style="margin-top:16px">And {subs.length - 40} more.</p>}
      </div>
    </section>
  )}

  <section class="band butter">
    <div class="wrap" style="display:flex;justify-content:space-between;align-items:center;gap:32px;flex-wrap:wrap">
      <div style="max-width:700px"><p class="eyebrow" style="color:var(--navy)">A neighbor to ask</p><h3 style="margin-bottom:8px">Curious about living in {p.name}?</h3><p style="font-size:17px">Dillon is a local Realtor who loves these neighborhoods. Questions are always welcome, with no pressure.</p></div>
      <a class="btn" href={url('/ask-dillon')}>Explore living here</a>
    </div>
  </section>
  <Prefs />
  <script is:inline define:vars={{ NAME: p.name }}>
    var TLD = window.TL, a = document.getElementById('set-area'), f = document.getElementById('follow');
    function show() { var mine = TLD.area() === NAME, fol = TLD.follows().indexOf(NAME) > -1;
      a.textContent = mine ? 'This is your area' : 'Make this my area'; a.classList.toggle('line', mine);
      f.textContent = fol ? 'Following ' + NAME : 'Follow ' + NAME; f.classList.toggle('gold', fol); }
    a.addEventListener('click', function () { TLD.setArea(TLD.area() === NAME ? '' : NAME); show(); });
    f.addEventListener('click', function () { var l = TLD.follows(), i = l.indexOf(NAME); if (i > -1) l.splice(i, 1); else l.push(NAME); TLD.setFollows(l); show(); });
    show(); document.querySelectorAll('.nl-return').forEach(function (r) { r.value = location.origin + location.pathname; });
  </script>
</Base>

