export function getStaticPaths() { return events().map((e) => ({ params: { slug: e.slug }, props: { e } })); }
const { e } = Astro.props;
const place = venuePlace(e), m = media(e) || (place ? media(place) : null);
const web = e.eventLink.replace(/^https?:\/\/(www\.)?/, '').replace(/\/.*$/, '');
const dates = e.starts && e.ends && e.ends !== e.starts ? `${dateText(e.starts)} to ${dateText(e.ends)}` : dateText(e.starts);
const where = place ? place.name : e.venue || e.profile;
---
<Base title={e.title} description={e.summary} active="Things to do">
  <section class="band hero">
    <div class="wrap" style="display:grid;grid-template-columns:repeat(12,minmax(0,1fr));column-gap:24px;align-items:center">
      <div style="grid-column:span 8">
        <p class="meta" style="margin-bottom:12px"><a href={url('/things-to-do')} style="font-weight:700">Things to do</a> &rsaquo; {e.eventType || 'Event'}</p>
        <div style="display:flex;gap:8px;margin-bottom:16px;flex-wrap:wrap"><span class="tag">{e.eventType || 'Event'}</span><span class="tag soft">{eventDates(e)}</span></div>
        <h1 style="margin-bottom:16px">{e.title}</h1>
        {e.summary && <p class="lead" style="margin-bottom:28px">{e.summary}</p>}
        <div style="display:flex;gap:12px;flex-wrap:wrap">{e.eventLink && <a class="btn" href={e.eventLink} rel="noopener">Visit {web}</a>}<button class="btn line" id="ics">Add to calendar</button></div>
      </div>
      <div style="grid-column:span 4">{m ? <img class="photo" style="height:300px;border-radius:16px" src={m.src} alt={m.alt} /> : <div class="ph" style="height:300px;border-radius:16px">Event image</div>}</div>
    </div>
  </section>
  <section class="band">
    <div class="wrap">
      <p class="eyebrow">The details</p><h2 style="margin-bottom:28px">Plan your visit</h2>
      <div class="grid g3">
        <div class="card pad"><p class="eyebrow">When</p><p style="font-size:20px;font-weight:700">{dates}</p>{(e.startTime || e.endTime) && <p class="meta" style="margin-top:6px">{[e.startTime, e.endTime].filter(Boolean).join(' to ')}</p>}</div>
        <div class="card pad"><p class="eyebrow">Where</p>{where ? <p style="font-size:20px;font-weight:700">{place ? <a href={href(place)}>{place.name}</a> : where}</p> : <p class="meta">Location coming soon.</p>}{e.address && <p class="meta" style="margin-top:6px">{e.address}</p>}</div>
        <div class="card pad"><p class="eyebrow">Cost</p><p style="font-size:20px;font-weight:700">{e.cost || 'Check the event site'}</p></div>
      </div>
      <p class="meta" style="margin-top:20px">Dates and prices can change, so check the event site before you go.</p>
      {e.tags.length > 0 && <div class="chips" style="margin-top:20px">{e.tags.map((t) => <span class="chip">{t}</span>)}</div>}
      <div class="card pad pick" style="padding:32px;margin-top:40px;max-width:760px">
        <p class="eyebrow">In the Loop</p><h3 style="margin-bottom:8px">Do not miss the next one.</h3>
        <p class="meta" style="margin-bottom:20px;font-size:16px">Every Monday: three local finds, the weekend list, and what just opened.</p>
        <form action={config.newsletterAction} method="post" style="display:flex;gap:10px;flex-wrap:wrap">
          <div style="flex:1;min-width:220px"><label class="sr" for="ev-email">Your email</label><input id="ev-email" name="email" type="email" required placeholder="name@email.com" /></div>
          <input type="text" name="company" tabindex="-1" autocomplete="off" aria-hidden="true" style="position:absolute;left:-9999px" /><input type="hidden" name="return" class="nl-return" />
          <button class="btn" type="submit">Join In the Loop</button>
        </form>
      </div>
    </div>
  </section>
  <script is:inline define:vars={{ T: e.title, S: e.starts, E: e.ends || e.starts, W: where, L: e.eventLink }}>
    document.querySelectorAll('.nl-return').forEach(function (r) { r.value = location.origin + location.pathname; });
    function ymd(s) { var m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(s || ''); return m ? m[3] + ('0' + m[1]).slice(-2) + ('0' + m[2]).slice(-2) : ''; }
    document.getElementById('ics').addEventListener('click', function () {
      var a = ymd(S), b = ymd(E) || a; if (!a) { alert('This event has no date yet.'); return; }
      var end = new Date(+b.slice(0, 4), +b.slice(4, 6) - 1, +b.slice(6, 8) + 1), pad = function (n) { return ('0' + n).slice(-2); };
      var endStr = end.getFullYear() + pad(end.getMonth() + 1) + pad(end.getDate());
      var ics = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Tradition Local//EN', 'BEGIN:VEVENT', 'UID:' + a + '-' + T.replace(/\W+/g, '') + '@traditionlocal.com', 'DTSTAMP:' + a + 'T000000Z', 'DTSTART;VALUE=DATE:' + a, 'DTEND;VALUE=DATE:' + endStr,
        'SUMMARY:' + T.replace(/[,;]/g, ' '), 'LOCATION:' + (W || '').replace(/[,;]/g, ' '), 'DESCRIPTION:' + (L || ''), 'END:VEVENT', 'END:VCALENDAR'].join('\r\n');
      var blob = new Blob([ics], { type: 'text/calendar' }), link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = 'event.ics'; link.click();
    });
  </script>
</Base>

scripts/sheet-export-core.cjs:
// Turns rows from the Simple Master sheet into the two public data files the site reads.
// Plain functions only, so the same code runs inside the sheet (Apps Script) and in Node for tests.
// Private columns (editor notes, sources, record IDs, example flags, media notes) are never copied.

var PROFILE_COLUMNS = ['slug', 'name', 'type', 'area', 'summary', 'description', 'status', 'address', 'website', 'phone', 'postal_city', 'hero_image', 'hero_alt',
  'hero_credit', 'hero_rights', 'gallery', 'video', 'faqs', 'typical_homes', 'local_take', 'best_for', 'school_district', 'zip_codes', 'region', 'sub_category', 'tags',
  'show_living', 'show_reviews', 'show_nearby', 'show_events', 'show_newsletter', 'show_faq', 'show_media', 'page_status'];
var CONTENT_COLUMNS = ['slug', 'type', 'title', 'profile', 'summary', 'body', 'author', 'review_date', 'rating', 'hero_image', 'hero_alt', 'hero_credit', 'hero_rights',
  'gallery', 'video', 'starts', 'ends', 'timezone', 'event_link', 'faqs', 'cost', 'venue_name', 'address', 'city', 'zip_code', 'event_type', 'start_time', 'end_time',
  'tags', 'show_media', 'show_faq', 'page_status'];

function slugify(s) {
  return String(s || '').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}
// Editor notes hold a few public facts as "Key: value" lines. Only these keys are read, nothing else leaves the sheet.
function noteValue(notes, key) {
  var lines = String(notes || '').split('\n');
  for (var i = 0; i < lines.length; i++) {
    var m = lines[i].match(/^\s*([A-Za-z_ ]+?)\s*:\s*(.*)$/);
    if (m && m[1].toLowerCase() === key.toLowerCase()) return m[2].trim();
  }
  return '';
}
function cleanZip(z) { return String(z || '').replace(/\.0\b/g, '').trim(); }
function lower(v) { return String(v || '').trim().toLowerCase(); }

// rows: array of objects keyed by the sheet's header names. options: { mode: 'preview' | 'production' }
function toPublicProfiles(rows, options) {
  var production = options && options.mode === 'production';
  var out = [];
  rows.forEach(function (r) {
    if (!String(r['Name'] || '').trim()) return;
    if (production && (lower(r['Page']) !== 'published' || lower(r['Example']) === 'yes')) return;
    var n = r['Editor notes'];
    out.push({
      slug: r['Slug'] || slugify(r['Name']), name: r['Name'], type: r['Profile type'], area: r['Area'], summary: r['Summary'], description: r['Full description'],
      status: r['Business status'], address: r['Address'], website: r['Website'], phone: r['Phone'], postal_city: r['Postal city'],
      hero_image: r['Hero image'], hero_alt: r['Image alt text'], hero_credit: r['Media credit'], hero_rights: r['Media rights'], gallery: r['Gallery'], video: r['Video'],
      faqs: r['FAQs'], typical_homes: r['Typical homes'], local_take: r['Local take'], best_for: noteValue(n, 'Best For'), school_district: noteValue(n, 'School District'),
      zip_codes: cleanZip(noteValue(n, 'Zip Codes')), region: noteValue(n, 'Region'), sub_category: noteValue(n, 'Sub Category'), tags: noteValue(n, 'Tags'),
      show_living: r['Living section'], show_reviews: r['Reviews section'], show_nearby: r['Nearby section'], show_events: r['Events section'],
      show_newsletter: r['Newsletter section'], show_faq: r['FAQ section'], show_media: r['Media section'], page_status: r['Page']
    });
  });
  return out;
}
function toPublicContent(rows, options) {
  var production = options && options.mode === 'production';
  var out = [];
  rows.forEach(function (r) {
    if (!String(r['Title'] || '').trim()) return;
    if (production && (lower(r['Page']) !== 'published' || lower(r['Example']) === 'yes')) return;
    var n = r['Editor notes'];
    out.push({
      slug: r['Slug'] || slugify(r['Title']), type: r['Content type'], title: r['Title'], profile: r['Profile'], summary: r['Summary'], body: r['Body'], author: r['Author'],
      review_date: dateText(r['Original review date']), rating: r['Rating'], hero_image: r['Hero image'], hero_alt: r['Image alt text'], hero_credit: r['Media credit'],
      hero_rights: r['Media rights'], gallery: r['Gallery'], video: r['Video'], starts: dateText(r['Starts']), ends: dateText(r['Ends']), timezone: r['Time zone'],
      event_link: r['Event link'], faqs: r['FAQs'], cost: noteValue(n, 'cost'), venue_name: noteValue(n, 'venue_name'), address: noteValue(n, 'address'),
      city: noteValue(n, 'city'), zip_code: cleanZip(noteValue(n, 'zip_code')), event_type: noteValue(n, 'event_type'), start_time: noteValue(n, 'start_time'),
      end_time: noteValue(n, 'end_time'), tags: noteValue(n, 'tags'), show_media: r['Media section'], show_faq: r['FAQ section'], page_status: r['Page']
    });
  });
  return out;
}
// Dates may arrive as real dates (from the sheet) or as text. The site reads M/D/YYYY.
function dateText(v) {
  if (v === null || v === undefined || v === '') return '';
  if (Object.prototype.toString.call(v) === '[object Date]') return (v.getMonth() + 1) + '/' + v.getDate() + '/' + v.getFullYear();
  return String(v).trim();
}
function csvCell(v) {
  var s = (v === null || v === undefined) ? '' : String(v);
  return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
function toCSV(rows, columns) {
  var lines = [columns.join(',')];
  rows.forEach(function (r) { lines.push(columns.map(function (c) { return csvCell(r[c]); }).join(',')); });
  return lines.join('\n') + '\n';
}
if (typeof module !== 'undefined') module.exports = { PROFILE_COLUMNS: PROFILE_COLUMNS, CONTENT_COLUMNS: CONTENT_COLUMNS, toPublicProfiles: toPublicProfiles, toPublicContent: toPublicContent, toCSV: toCSV, slugify: slugify };

src/pages/account.astro:
---
import Base from '../layouts/Base.astro';
import Prefs from '../components/Prefs.astro';
import '../styles/pages.css';
import { businesses, href, url } from '../lib/data';
import { areaPages, bizIn, topRating, category } from '../lib/helpers';
import { config } from '../config';
const areas = areaPages().map((p) => p.name).sort();
const index = businesses().map((b) => ({ s: b.slug, n: b.name, a: b.area, c: category(b), r: topRating(b.name), u: href(b) }));
const topics = [['food', 'Food and drink'], ['things', 'Things to do'], ['openings', 'New openings'], ['homes', 'Neighborhoods and homes']];
---
<Base title="Your account" description="Your area, the places you follow, and what you receive.">
  <section class="band hero"><div class="wrap"><p class="eyebrow">Your account</p><h1 style="margin-bottom:12px">Account and settings</h1><p class="lead">Choose your area, follow the places you care about, and decide what you receive.</p>
    <p class="meta" style="margin-top:16px">Your choices are saved on this device. Sign in is coming, and we will move them to your account then.</p></div></section>
  <section class="band">
    <div class="wrap" style="display:flex;flex-wrap:wrap;gap:56px;align-items:flex-start">
      <nav aria-label="Account sections" style="flex:0 0 240px"><a class="menu" href="#areas">Your areas</a><a class="menu" href="#locally">Locally</a><a class="menu" href="#loop">In the Loop</a><a class="menu" href="#saved">Saved places</a><a class="menu" href="#privacy">Privacy and data</a></nav>
      <div class="stack" style="flex:999 1 560px;min-width:0">

        <div class="panel" id="areas"><p class="eyebrow">Your areas</p><h2 style="font-size:32px;margin-bottom:8px">Where do you call home?</h2>
          <p class="meta" style="font-size:16px;margin-bottom:20px">We use this for your local picks and to open Food on your area first.</p>
          <div style="max-width:380px"><label for="a-home">Your area</label><select id="a-home"><option value="">Choose an area</option>{areas.map((a) => <option>{a}</option>)}<option value="__other">Other</option></select></div>
          <div id="a-other-wrap" hidden style="max-width:380px;margin-top:12px"><label for="a-other">Your area or ZIP code</label><input id="a-other" type="text" placeholder="Try Cypress or 77449" /></div>
          <p style="font-size:13px;font-weight:700;margin:28px 0 10px">Areas you follow</p>
          <div class="chips" id="a-follow"></div>
          <div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:16px;max-width:520px"><div style="flex:1;min-width:220px"><label class="sr" for="a-add">Follow another area</label><select id="a-add"><option value="">Follow another area</option>{areas.map((a) => <option>{a}</option>)}</select></div><button class="btn line sm" id="a-add-btn" type="button">Follow</button></div>
          <div id="a-picks" style="margin-top:28px;padding:20px;border-radius:12px;background:var(--ivory)" hidden><p class="eyebrow" id="a-picks-h" style="margin-bottom:8px"></p><div id="a-picks-list"></div></div>
        </div>

        <div class="panel" id="locally"><p class="eyebrow">Locally</p><h2 style="font-size:32px;margin-bottom:8px">Your neighborhood, in your inbox</h2>
          <p class="meta" style="font-size:16px;margin-bottom:20px">Locally is a closer look at where you live, written for your area and the areas you follow. Separate from In the Loop.</p>
          <div style="margin-bottom:24px"><button class="chip" id="l-on" aria-pressed="false">Locally is on</button></div>
          <p style="font-size:13px;font-weight:700;margin-bottom:10px">What to include</p>
          <div class="chips" id="l-topics">{topics.map(([k, l]) => <button class="chip" data-k={k} aria-pressed="false">{l}</button>)}</div>
          <p style="font-size:13px;font-weight:700;margin:24px 0 10px">How often</p>
          <div class="chips" id="l-freq"><button class="chip" data-f="twice" aria-pressed="false">Twice a month</button><button class="chip" data-f="monthly" aria-pressed="false">Monthly</button></div>
          <p class="meta" style="margin-top:20px">We save these now. Locally emails start once sign in is connected.</p>
        </div>

        <div class="panel" id="loop"><p class="eyebrow">In the Loop</p><h2 style="font-size:32px;margin-bottom:8px">Every Monday, the same for everyone</h2>
          <p class="meta" style="font-size:16px;margin-bottom:20px">Food we trust, what is happening, and what just opened. It is not tailored to your area.</p>
          <form action={config.newsletterAction} method="post" style="display:flex;gap:10px;flex-wrap:wrap;max-width:560px">
            <div style="flex:1;min-width:240px"><label class="sr" for="loop-email">Your email</label><input id="loop-email" name="email" type="email" required placeholder="name@email.com" /></div>
            <input type="text" name="company" tabindex="-1" autocomplete="off" aria-hidden="true" style="position:absolute;left:-9999px" /><input type="hidden" name="return" id="loop-return" />
            <button class="btn" type="submit">Join In the Loop</button>
          </form>
        </div>

        <div class="panel" id="saved"><p class="eyebrow">Saved places</p><h2 style="font-size:32px;margin-bottom:8px">Your list</h2>
          <p class="meta" style="font-size:16px;margin-bottom:12px">Places you saved on Food, ready whenever you are.</p>
          <div id="s-list"></div><p style="margin-top:16px"><a href={url('/food')} style="font-weight:700">Find more places</a></p></div>

        <div class="panel" id="privacy"><p class="eyebrow">Privacy and data</p><h2 style="font-size:32px;margin-bottom:8px">You are in control</h2>
          <p class="meta" style="font-size:16px;margin-bottom:12px">We never sell your email, and you can leave at any time.</p>
          <div class="row"><div style="flex:1;min-width:240px"><b>Clear what is saved on this device</b><br /><span class="meta">Your area, followed areas, Locally choices, and saved places.</span></div><button class="btn line sm" id="p-clear" type="button">Clear</button></div></div>
      </div>
    </div>
  </section>
  <Prefs />
  <script is:inline define:vars={{ INDEX: index }}>
    var TLD = window.TL, $ = function (id) { return document.getElementById(id); };
    function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]; }); }
    $('loop-return').value = location.origin + location.pathname;
    var home = $('a-home'), other = $('a-other');
    function areaName() { var v = TLD.area(); return v; }
    function initHome() { var v = TLD.area(), opts = [].map.call(home.options, function (o) { return o.value; });
      if (!v) home.value = ''; else if (opts.indexOf(v) > -1) home.value = v; else { home.value = '__other'; other.value = v; } $('a-other-wrap').hidden = home.value !== '__other'; }
    function picks() { var a = TLD.area(), box = $('a-picks'); if (!a || a === '__other') { box.hidden = true; return; }
      var list = INDEX.filter(function (x) { return x.a === a; }).sort(function (x, y) { return y.r - x.r; }).slice(0, 3); box.hidden = !list.length; if (!list.length) return;
      $('a-picks-h').textContent = 'Local picks for ' + a;
      $('a-picks-list').innerHTML = list.map(function (x) { return '<div class="row" style="border-top:1px solid var(--line)"><b style="flex:1"><a href="' + esc(x.u) + '">' + esc(x.n) + '</a></b><span class="meta">' + esc(x.c) + (x.r ? ', ' + x.r + ' out of 5' : '') + '</span></div>'; }).join(''); }
    function follows() { var f = TLD.follows(); $('a-follow').innerHTML = f.length ? f.map(function (a) { return '<button class="chip on" data-a="' + esc(a) + '" title="Unfollow">' + esc(a) + ' &times;</button>'; }).join('') : '<span class="meta">You are not following any areas yet.</span>'; }
    home.addEventListener('change', function () { if (home.value === '__other') { $('a-other-wrap').hidden = false; TLD.setArea(other.value.trim()); } else { $('a-other-wrap').hidden = true; TLD.setArea(home.value); } picks(); });
    other.addEventListener('input', function () { TLD.setArea(other.value.trim()); picks(); });
    $('a-follow').addEventListener('click', function (e) { var b = e.target.closest('button'); if (!b) return; var f = TLD.follows().filter(function (x) { return x !== b.dataset.a; }); TLD.setFollows(f); follows(); });
    $('a-add-btn').addEventListener('click', function () { var v = $('a-add').value; if (!v) return; var f = TLD.follows(); if (f.indexOf(v) < 0) f.push(v); TLD.setFollows(f); $('a-add').value = ''; follows(); });
    var pref = TLD.get('tl_locally', { on: true, topics: { food: true, things: true, openings: false, homes: true }, freq: 'twice' });
    function savePref() { TLD.set('tl_locally', pref); }
    function drawLocally() { var on = $('l-on'); on.classList.toggle('on', pref.on); on.setAttribute('aria-pressed', pref.on); on.textContent = pref.on ? 'Locally is on' : 'Locally is off';
      document.querySelectorAll('#l-topics button').forEach(function (b) { var v = !!pref.topics[b.dataset.k]; b.classList.toggle('on', v); b.setAttribute('aria-pressed', v); });
      document.querySelectorAll('#l-freq button').forEach(function (b) { var v = pref.freq === b.dataset.f; b.classList.toggle('on', v); b.setAttribute('aria-pressed', v); }); }
    $('l-on').addEventListener('click', function () { pref.on = !pref.on; savePref(); drawLocally(); });
    $('l-topics').addEventListener('click', function (e) { var b = e.target.closest('button'); if (!b) return; pref.topics[b.dataset.k] = !pref.topics[b.dataset.k]; savePref(); drawLocally(); });
    $('l-freq').addEventListener('click', function (e) { var b = e.target.closest('button'); if (!b) return; pref.freq = b.dataset.f; savePref(); drawLocally(); });
    function saved() { var s = TLD.saved(), box = $('s-list'); var rows = s.map(function (slug) { return INDEX.filter(function (x) { return x.s === slug; })[0]; }).filter(Boolean);
      box.innerHTML = rows.length ? rows.map(function (x) { return '<div class="row"><div style="flex:1;min-width:220px"><a href="' + esc(x.u) + '" style="font-size:18px;font-weight:700">' + esc(x.n) + '</a><br><span class="meta">' + esc([x.c, x.a].filter(Boolean).join(', ')) + '</span></div><button class="btn line sm" data-slug="' + esc(x.s) + '" type="button">Remove</button></div>'; }).join('') : '<div class="row"><span class="meta">Nothing saved yet. Tap the heart on any place to add it here.</span></div>'; }
    $('s-list').addEventListener('click', function (e) { var b = e.target.closest('button'); if (!b) return; TLD.toggleSaved(b.dataset.slug); saved(); });
    $('p-clear').addEventListener('click', function () { if (!confirm('Clear your saved choices on this device?')) return; ['tl_area', 'tl_follows', 'tl_saved', 'tl_locally'].forEach(function (k) { try { localStorage.removeItem(k); } catch (e) {} }); location.reload(); });
    initHome(); picks(); follows(); drawLocally(); saved();
  </script>
</Base>

src/pages/ask-dillon.astro:
---
import Base from '../layouts/Base.astro';
import '../styles/pages.css';
import { url } from '../lib/data';
import { areaPages, bizIn, subsIn } from '../lib/helpers';
import { config } from '../config';
const popular = areaPages().map((p) => ({ n: p.name, w: bizIn(p.name).length + subsIn(p.name).length })).sort((a, b) => b.w - a.w).slice(0, 10).map((x) => x.n);
const topics = [['Neighborhood guide', 'Get a feel for the area and daily life.'], ['Food and coffee', 'Find your next restaurant or favorite cafe.'], ['Things to do', 'Parks, outings, and local events.'],
  ['Homes and market trends', 'Home styles, prices, and market updates.'], ['Schools', 'Districts and what to check for an address.'], ['Moving to the area', 'Practical resources for your next move.']];
---
<Base title="Ask Dillon" active="More" sub="makeithome" description="Tell us which Houston neighborhoods you are curious about, and Dillon will reply personally.">
  <section class="band hero"><div class="wrap"><p class="eyebrow">A neighbor to ask</p><h1 style="margin-bottom:16px">Get to know a neighborhood.</h1><p class="lead">Tell us what matters to you, and Dillon will reply personally. Questions are always welcome, with no pressure.</p></div></section>
  <section class="band">
    <div class="wrap split">
      <div class="main">
        <div class="panel" id="ask-thanks" hidden style="border-color:var(--gold)">
          <p class="eyebrow">Thank you</p><h2 id="ask-title" style="margin-bottom:12px">Your request is in.</h2>
          <p style="font-size:18px;margin-bottom:20px">Dillon will reply personally. In the meantime, here are a few places to start.</p>
          <div style="display:flex;gap:12px;flex-wrap:wrap"><a class="btn" href={url('/neighborhoods')}>Explore neighborhoods</a><a class="btn line" href={url('/find-your-fit')}>Find your fit</a></div>
        </div>
        <form class="panel" id="ask-form" novalidate data-endpoint={config.newsletterAction} data-contact={config.contactEmail}>
          <fieldset style="border:0;padding:0;margin:0 0 24px"><legend style="font-size:13px;font-weight:700;margin-bottom:10px">Where are you curious about? Choose one or more.</legend>
            <div class="chips" id="ask-areas">{[...popular, 'Somewhere else'].map((a) => <label class="chip" style="cursor:pointer"><input type="checkbox" name="areas" value={a} style="position:absolute;opacity:0;width:1px;height:1px" />{a}</label>)}</div>
            <div id="ask-else-wrap" hidden style="margin-top:12px;max-width:380px"><label for="ask-else">Which area?</label><input id="ask-else" type="text" placeholder="Try Cypress or 77449" /></div>
            <p class="msg-err" id="ask-area-err" hidden>Choose at least one area.</p>
          </fieldset>
          <fieldset style="border:0;padding:0;margin:0 0 24px"><legend style="font-size:13px;font-weight:700;margin-bottom:10px">What would you like to know?</legend>
            <div class="chips" id="ask-topics">{topics.map(([t]) => <label class="chip" style="cursor:pointer"><input type="checkbox" name="topics" value={t} style="position:absolute;opacity:0;width:1px;height:1px" />{t}</label>)}</div></fieldset>
          <div class="grid g2" style="margin-bottom:20px">
            <div><label for="ask-first">First name</label><input id="ask-first" type="text" autocomplete="given-name" placeholder="Your first name" /><p class="msg-err" id="ask-first-err" hidden>Please add your first name.</p></div>
            <div><label for="ask-email">Email</label><input id="ask-email" type="email" autocomplete="email" placeholder="name@email.com" /><p class="msg-err" id="ask-email-err" hidden>Enter an email address like name@company.com</p></div>
          </div>
          <div style="margin-bottom:20px"><label for="ask-note">Anything else? Optional</label><textarea id="ask-note" placeholder="Tell us about your timing, budget, or what you are hoping for."></textarea></div>
          <label style="display:flex;gap:10px;align-items:flex-start;font-weight:400;margin-bottom:20px"><input id="ask-sub" type="checkbox" checked style="width:auto;min-height:0;margin-top:4px" /><span>Also send me In the Loop, every Monday.</span></label>
          <input id="ask-company" type="text" tabindex="-1" autocomplete="off" aria-hidden="true" style="position:absolute;left:-9999px" />
          <button class="btn" id="ask-send" type="submit" style="min-height:52px">Send my request</button>
          <p class="msg-err" id="ask-fail" hidden></p>
          <p class="meta" style="margin-top:14px">By sending this, you agree to receive emails from Tradition Local. You can unsubscribe anytime. We only call or text if you ask us to.</p>
        </form>
      </div>
      <div class="side">
        <div class="card pad"><p class="eyebrow">What to expect</p>
          <div class="row" style="border-top:0"><span class="tag">1</span><div><b>Dillon reads it</b><br /><span class="meta">Every request is read by a person.</span></div></div>
          <div class="row"><span class="tag">2</span><div><b>A personal reply</b><br /><span class="meta">A short local overview that fits what you asked.</span></div></div>
          <div class="row"><span class="tag">3</span><div><b>No pressure</b><br /><span class="meta">Take your time. Ask as much as you like.</span></div></div></div>
        <div class="card pad" style="margin-top:24px;background:var(--butter);border-color:var(--butter)"><p class="eyebrow" style="color:var(--navy)">Prefer to explore first?</p><p style="margin-bottom:16px">Try the quiz to see which neighborhoods match what you love.</p><a class="btn" href={url('/find-your-fit')}>Find your fit</a></div>
      </div>
    </div>
  </section>
  <script is:inline>
    var form = document.getElementById('ask-form'), $ = function (id) { return document.getElementById(id); };
    function paint() { form.querySelectorAll('label.chip').forEach(function (l) { var c = l.querySelector('input'); l.classList.toggle('on', c.checked); }); $('ask-else-wrap').hidden = !form.querySelector('input[value="Somewhere else"]').checked; }
    form.addEventListener('change', paint); paint();
    function checked(name) { return [].map.call(form.querySelectorAll('input[name=' + name + ']:checked'), function (x) { return x.value; }); }
    function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]; }); }
    form.addEventListener('submit', async function (e) {
      e.preventDefault();
      var picked = checked('areas'), first = $('ask-first').value.trim(), em = $('ask-email').value.trim(), elseVal = $('ask-else').value.trim();
      var areaOk = picked.length > 0, nameOk = first.length > 0, emOk = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em);
      $('ask-area-err').hidden = areaOk; $('ask-first-err').hidden = nameOk; $('ask-email-err').hidden = emOk;
      if (!areaOk || !nameOk || !emOk) return;
      var areas = picked.filter(function (a) { return a !== 'Somewhere else'; }); if (picked.indexOf('Somewhere else') > -1) areas.push(elseVal || 'Somewhere else');
      var payload = { first_name: first, email: em, areas: areas, address: '', topics: checked('topics'), note: $('ask-note').value.trim(), subscribe: $('ask-sub').checked, company: $('ask-company').value };
      var btn = $('ask-send'), fail = $('ask-fail'); fail.hidden = true; btn.disabled = true; btn.textContent = 'Sending...';
      try {
        var res = await fetch(form.dataset.endpoint, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
        var out = await res.json(); if (!out.ok) throw new Error('rejected');
        $('ask-title').textContent = 'Thank you, ' + first + '.'; form.hidden = true; $('ask-thanks').hidden = false; window.scrollTo({ top: 0 });
      } catch (err) {
        fail.textContent = 'We could not send your request. Please try again in a moment, or email us at ' + form.dataset.contact + '.'; fail.hidden = false;
      } finally { btn.disabled = false; btn.textContent = 'Send my request'; }
    });
  </script>
</Base>
